<div class="card" style="max-width:760px"><div class="card-header"><h3>⚙️ Parámetros operativos</h3></div><div class="card-body"><div id="configMsg"></div><div class="form-group"><label class="form-label">Hora límite (HH:MM)</label><input id="hora_limite" class="form-control" value="09:00"></div><div class="form-group"><label class="form-label">Tarifa pensionado (Bs)</label><input id="tarifa_pensionado" type="number" min="0.01" step="0.01" class="form-control" value="15"></div><div class="form-group"><label class="form-label">Tarifa esporádico (Bs)</label><input id="tarifa_esporadico" type="number" min="0.01" step="0.01" class="form-control" value="18"></div><div class="form-group"><label class="form-label">Mínimo mensual de almuerzos</label><input id="minimo_pension" type="number" min="1" step="1" class="form-control" value="10"></div><button class="btn btn-primary" onclick="guardar()">Guardar parámetros</button></div></div>
<script>async function cargar(){const r=await apiGet('/backend/api/configuracion.php',{action:'listar'});(r.data||[]).forEach(x=>{const e=document.getElementById(x.clave);if(e)e.value=x.valor;});}async function guardar(){for(const k of ['hora_limite','tarifa_pensionado','tarifa_esporadico','minimo_pension']){const r=await apiPost('/backend/api/configuracion.php',{action:'guardar',clave:k,valor:document.getElementById(k).value});if(!r.success){document.getElementById('configMsg').innerHTML='<div class="alert alert-danger">'+r.message+'</div>';return;}}document.getElementById('configMsg').innerHTML='<div class="alert alert-success">Parámetros guardados correctamente.</div>';}cargar();</script>
<?php require_once __DIR__.'/layout_end.php'; ?>
